const payload = $input.first().json.body ?? $input.first().json;

const contactId   = payload.contact?.id;
const nomeCliente = payload.contact?.name ?? 'Sem nome';
const telefone    = payload.contact?.phonenumber ?? '';
const sessionId   = payload.sessionId ?? payload.session?.id;

if (!contactId) throw new Error('contactId não encontrado no payload');

const annotation = (payload.contact?.annotation ?? '').replace(/\\n/g, '\n');

const extrairLinha = (rotulo) => {
  const regex = new RegExp(`^\\d+\.\\s*${rotulo}:\\s*(.+)$`, 'im');
  const match = annotation.match(regex);
  return match ? match[1].trim() : 'Não informado';
};

const statusAtual   = extrairLinha('Status Atual');
const estagioParado = extrairLinha('Estágio Parado');
const dorPrincipal  = extrairLinha('Dor Principal');
const resumoRapido  = extrairLinha('Resumo Rápido');
const instrucao     = extrairLinha('Instrução para o Futuro');

let agendamento = 'Não informado';
const matchData = resumoRapido.match(
  /(\d{1,2}\/\d{1,2}(?:\/\d{2,4})?)\s+às\s+(\d{1,2}[h:]\d{0,2})/i
);
if (matchData) {
  const hora = matchData[2].replace('h', 'h').padEnd(5, '00');
  agendamento = `${matchData[1]} às ${hora}`;
}

const agora = new Date();
const dataMovimento = agora.toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const horaMovimento = agora.toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' });

return [{
  json: {
    contactId,
    nomeCliente,
    telefone,
    sessionId,
    statusAtual,
    estagioParado,
    dorPrincipal,
    resumoRapido,
    instrucao,
    agendamento,
    dataMovimento,
    horaMovimento
  }
}];

const resposta = $input.first().json;
const items = resposta.items ?? [];

if (items.length === 0) throw new Error('Nenhum card encontrado para esse contato no painel');

const card = items[0];
const cardId = card.id;

// Tags que já existem no card — preserva todas
const tagsExistentes = card.tagIds ?? [];

// Tag nova a adicionar (etiqueta do painel CRM)
const TAG_NOVA = '49db1722-82f2-489b-9298-6a027af7fdc2';

// Merge: mantém as existentes + adiciona a nova sem duplicar
const tagsFinal = [...new Set([...tagsExistentes, TAG_NOVA])];

const d = $('Extrair Dados do Payload1').first().json;

const descricao = [
  `📅 CONSULTA AGENDADA`,
  `Data/Hora: ${d.agendamento}`,
  ``,
  `👤 LEAD`,
  `Nome: ${d.nomeCliente}`,
  `Telefone: ${d.telefone}`,
  ``,
  `📋 RESUMO DA CONVERSA`,
  d.resumoRapido,
  ``,
  `🎯 STATUS & ESTÁGIO`,
  `Status: ${d.statusAtual}`,
  `Estágio parado: ${d.estagioParado}`,
  ``,
  `🦷 DOR PRINCIPAL`,
  d.dorPrincipal,
  ``,
  `🔜 INSTRUÇÃO PARA O FUTURO`,
  d.instrucao,
  ``,
  `─────────────────────────`,
  `✅ Movimentado pela IA em ${d.dataMovimento} às ${d.horaMovimento}`
].join('\n');

const requestBody = {
  fields: ['StepId', 'Description', 'TagIds'],
  stepId: '8f9dc89b-dfdf-45de-92c3-9b875abc5178',
  description: descricao,
  tagIds: tagsFinal
};

return [{ json: { cardId, requestBody, contactId: d.contactId } }];
